SELECT * FROM PRODUCT_TBL P INNER JOIN SELLER_INFO_TBL S ON P.STORE_ID = S.STORE_ID WHERE 1=1
AND P.STORE_ID = #{storeId}
AND STORE_AREA = #{area}
AND PRO_NAME LIKE '%' || #{keyword} || '%'
AND PRO_TYPE = #{category}
ORDER BY CASE WHEN S.MEMBERSHIP = 'Y' THEN 0 ELSE 1 END,
P.CNT DESC
P.SELL_COUNT DESC
P.CREATED_AT DESC
P.CREATED_AT DESC


SELECT CLICK_UNIT_COST AS clickUnitCost
FROM AD_TBL
WHERE AD_ID = #{adId}

mapper.update:
UPDATE AD_TBL SET
	CLICKS = CLICKS + 1
WHERE AD_ID =  #{adId}

		UPDATE AD_HISTORY_TBL SET
			MONTHLY_CLICKS = MONTHLY_CLICKS + 1,
        	MONTHLY_COST = MONTHLY_COST + #{clickUnitCost}  
        WHERE AD_ID = #{adId}
      	AND PER_MONTH = TO_DATE(#{currentMonth}, 'YYYY-MM-DD HH24:MI:SS')

