SELECT * FROM PRODUCT_TBL P INNER JOIN SELLER_INFO_TBL S ON P.STORE_ID = S.STORE_ID WHERE NOT EXISTS ( SELECT 1 FROM PRODUCT_INGREDIENT_TBL G INNER JOIN INGREDIENT_TBL I ON G.INGREDIENT_ID = I.INGREDIENT_ID WHERE P.PRO_NO = G.PRO_NO AND I.INGREDIENT_NAME IN
#{item}
